UPDATE search_sync_state s SET running_task_id=#{taskId}, running_lease_owner=#{owner}
WHERE s.task_type=#{type} AND s.biz_key=#{key} AND s.requested_version=#{version}
  AND s.published_version < #{version} AND 
  AND NOT EXISTS (SELECT 1 FROM business_task previous
                WHERE previous.task_id=s.running_task_id AND previous.lease_owner=s.running_lease_owner
                  AND previous.status='RUNNING' AND previous.lease_until > UTC_TIMESTAMP(6))

